# Default motion/facial for each character
DEFAULT_MOTION = {
    1: "w-normal-greeting01",
    2: "w-normal-greeting01",
    3: "w-normal-greeting01",
    4: "w-normal-default01",
}

DEFAULT_FACIAL = {
    1: "face_smile_01",
    2: "face_smile_01",
    3: "face_smile_01",
    4: "face_normal_01",
}

def get_valid_motions(model_id: int) -> set:
    """获取指定角色可用的 body motion 集合"""
    return CHARACTER_MOTIONS.get(model_id, ALL_MOTIONS)

def get_valid_facials(model_id: int) -> set:
    """获取指定角色可用的 facial 集合"""
    return CHARACTER_FACIALS.get(model_id, ALL_FACIALS)

def get_default_motion(model_id: int) -> str:
    """获取指定角色的默认 motion"""
    return DEFAULT_MOTION.get(model_id, "w-normal-nod01")

def get_default_facial(model_id: int) -> str:
    """获取指定角色的默认 facial"""
    return DEFAULT_FACIAL.get(model_id, "face_smile_01")
